using System.ComponentModel;
using System.Text;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search functionality to the research agent.
/// Uses the Google Custom Search JSON API when configured, otherwise falls back
/// to a DuckDuckGo HTML scrape so the app remains functional without an API key.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        try
        {
            return await SearchViaDuckDuckGoAsync(query, maxResults);
        }
        catch (Exception ex)
        {
            return $"[Search error: {ex.Message}. The agent should try rephrasing the query or use existing notes to answer.]";
        }
    }

    private async Task<string> SearchViaDuckDuckGoAsync(string query, int maxResults)
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync();
        return ParseDuckDuckGoResults(html, maxResults);
    }

    private static string ParseDuckDuckGoResults(string html, int maxResults)
    {
        var results = new StringBuilder();
        var resultCount = 0;

