using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// ---------------------------------------------------------------------------
// Configuration — read from environment variables
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Dependency injection
// ---------------------------------------------------------------------------
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient();

services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(new ApiKeyCredential(apiKey))));

var sp = services.BuildServiceProvider();

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var httpClientFactory = sp.GetRequiredService<IHttpClientFactory>();

var webSearch = new WebSearchTool(httpClientFactory.CreateClient());
var notes = new NoteTool();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(notes.SaveNote),
    AIFunctionFactory.Create(notes.GetNotes),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
const string instructions = """
    You are a research agent. Your job is to thoroughly research a topic the
    user provides by searching the web, taking notes on what you find, and
    then producing a well-organized summary.

    Workflow:
    1. Break the topic into 2-4 sub-questions.
    2. For each sub-question, call SearchWebAsync with a focused query.
    3. After each search, call SaveNote with the key findings.
    4. When you have enough information, call GetNotes to review everything.
    5. Produce a final, well-structured summary with the key facts. Cite
       which search results informed each point.

    Guidelines:
    - Be thorough but concise.
    - If a search returns no useful results, rephrase and try again.
    - Do NOT fabricate information — only summarize what you found.
    """;

var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "Researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    },
    loggerFactory,
    sp);

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║         🔍  Research Agent  🔍              ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.      ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");
Console.WriteLine();

using var session = new AgentSession();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (the agent will search the web and take notes)");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
                Tools = [.. tools],
            },
        };

        var response = await agent.RunAsync(
            $"Research this topic and provide a comprehensive summary: {input}",
            session,
            runOptions,
            CancellationToken.None);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();

        foreach (var message in response.Messages)
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.WriteLine(message.Text);
            }
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

