+/// across multiple search iterations and produce a final summary.
+/// </summary>
+public sealed class NoteTool
+{
+    private readonly List<(string Topic, string Content)> _notes = [];
+
+    [Description("Saves a research note. Use this to record key findings from search results so they can be referenced later in the summary.")]
+    public string SaveNote(
+        [Description("A short topic label for the note")] string topic,
+        [Description("The content of the note")] string content)
+    {
+        _notes.Add((topic, content));
+        return $"Note #{_notes.Count} saved under topic \"{topic}\".";
+    }
+
+    [Description("Retrieves all saved notes. Use this before writing the final summary to review what has been collected.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "[No notes saved yet.]";
+
+        var sb = new StringBuilder();
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            var (topic, content) = _notes[i];
+            sb.AppendLine($"--- Note #{i + 1}: {topic} ---");
+            sb.AppendLine(content);
+            sb.AppendLine();
+        }
+
+        return sb.ToString();
+    }
+}
